List<User> users = getUserList();

// Filter: keep only active users, then get their names
List<String> activeNames = users.stream()
    .filter(user -> user.isActive())       // filter: User -> boolean
    .map(user -> user.getName())           // map: User -> String
    .collect(Collectors.toList());

// Shorter with method references
List<String> names = users.stream()
    .filter(User::isActive)
    .map(User::getName)
    .collect(Collectors.toList());
